"""Integration tests for the uniformly generated chained CLI."""

from __future__ import annotations

from pathlib import Path

from click.testing import CliRunner

from postgkyl.cli.app import (
    COMMAND_ALIASES,
    COMMANDS,
    COMMAND_SECTIONS,
    MODELS,
    cli,
)

ROOT = Path(__file__).parents[1]
DATA = ROOT / "tests" / "test_data"
FIELD = DATA / "rt_gk_tcv_iwl_adapt_source_1x2v_p1-ion_HamiltonianMoments_250.gkyl"
DISTF = DATA / "generated" / "distf_p2_0.gkyl"
ENERGY = DATA / "generated" / "energy_dynvec.gkyl"
FIELD_3D = DATA / "generated" / "3d_ms_p1.gkyl"


def _run(*args):
  return CliRunner().invoke(cli, [str(arg) for arg in args])


def _ok(*args):
  result = _run(*args)
  assert result.exit_code == 0, result.output
  return result


def test_every_registered_subcommand_is_generated():
  assert len(COMMANDS) == len(MODELS)
  assert {command.name
          for command in COMMANDS} == {model.name
                                       for model in MODELS}
  assert set(cli.commands) == {model.name for model in MODELS}


def test_help_groups_the_generated_inventory():
  result = _ok("--help")
  for section, names in COMMAND_SECTIONS.items():
    assert f"{section}:" in result.output
    assert names
  assert "rotations_bparrotate" in result.output
  assert "local_poly" in result.output


def test_removed_manual_commands_and_legacy_spellings_are_rejected():
  for spelling in (
      "bparrotate",
      "euler",
      "tenmoment",
      "status",
      "print",
      "dg_local_poly",
      "gk-load-quantity",
      "extractinput",
      "plotly-animate",
  ):
    assert _run(spelling).exit_code != 0


def test_aliases_only_add_spellings():
  assert dict(COMMAND_ALIASES) == {"pl": "plot", "ev": "evaluate"}
  assert cli.get_command(None, "pl") is cli.get_command(None, "plot")
  assert cli.get_command(None, "ev") is cli.get_command(None, "evaluate")


def test_bare_filename_is_a_spelling_for_canonical_load():
  bare = _ok(FIELD, "info")
  explicit = _ok("load", "--file_name", FIELD, "info")
  assert bare.output == explicit.output


def test_fluent_chain_uses_api_command_and_option_names():
  result = _ok(FIELD, "interpolate", "select", "--z0", "0", "--comp", "0",
               "info")
  assert "Number of components: 1" in result.output


def test_select_prioritizes_the_first_option_for_each_initial():
  select = next(command for command in COMMANDS if command.name == "select")
  options = {option.name: option.opts for option in select.params}
  assert options == {
      "comp": ["--comp", "-c"],
      "z0": ["--z0", "-z"],
      "z1": ["--z1"],
      "z2": ["--z2"],
      "z3": ["--z3"],
      "z4": ["--z4"],
      "z5": ["--z5"],
      "inplace": ["--inplace", "-i"],
      "tag": ["--tag", "-t"],
      "label": ["--label", "-l"],
  }
  result = _ok(FIELD, "interpolate", "select", "-c", "0", "-z", "0", "-t",
               "chosen", "info")
  assert result.output.startswith("(chosen#0)")


def test_api_underscores_are_the_only_cli_spellings():
  assert _run(DISTF, "local-poly").exit_code != 0
  assert _run("load", "--file-name", FIELD, "info").exit_code != 0
  _ok(DISTF, "local_poly", "--npoints", "3", "info")


def test_boolean_options_accept_an_optional_explicit_value():
  _ok(DISTF, "interpolate", "fft", "--psd", "info")
  _ok(DISTF, "interpolate", "fft", "--psd", "True", "info")
  _ok(DISTF, "interpolate", "fft", "--psd", "False", "info")


def test_declared_cli_arguments_are_positional():
  _ok(ENERGY, "ev", "f0 2 *", "info")
  assert _run(ENERGY, "evaluate", "--chain", "f 2 *").exit_code != 0

  _ok(FIELD_3D, "integrate", "2", "info")
  assert _run(FIELD_3D, "integrate", "--axis", "2").exit_code != 0
  assert _run(FIELD_3D, "integrate_axis", "2").exit_code != 0


def test_generated_save_options_match_python_parameter_names(tmp_path):
  output = tmp_path / "field"
  _ok(DISTF, "save", "--out_name", output, "--extension", "npy")
  assert _run(DISTF, "save", "--out-name", output).exit_code != 0
  assert output.with_suffix(".npy").is_file()
  assert _run(DISTF, "save", "--out", output).exit_code != 0


def test_plot_uses_generated_render_options(tmp_path):
  output = tmp_path / "field.png"
  _ok(FIELD, "interpolate", "select", "--comp", "0", "plot", "--no_show",
      "--grid_indices", "True", "--saveas", output)
  assert output.is_file()


def test_manual_session_render_options_are_not_registered():
  assert _run("--batch_mode", FIELD, "info").exit_code != 0
  assert _run("--saveframes-prefix", "frame", FIELD, "info").exit_code != 0


def test_version_and_unknown_command_edges():
  version = _ok("--version")
  assert "postgkyl" in version.output
  assert _run("definitely-not-a-command").exit_code != 0
"""Frozen, dependency-free records describing the generated CLI surface.

This package deliberately knows nothing about Click or postgkyl datasets.
API-owning modules attach these records to their public callables; the CLI is
the only layer that interprets them.
"""

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum, auto
from typing import Callable


class Section(Enum):
  """Top-level help sections, in display order."""

  VERBS = "Verbs"
  DIAGNOSTICS = "Diagnostics"
  RENDER = "Render"
  UTILITY = "Utility"


class Execution(Enum):
  """Closed set of working-set adapters used by the CLI runtime."""

  MAP_REPLACE = auto()
  MAP_APPEND = auto()
  MAP_OR_TERMINAL_EACH = auto()
  COMBINE = auto()
  TERMINAL_EACH = auto()
  TERMINAL_ALL = auto()
  LOAD = auto()


class ResultPolicy(Enum):
  """How a returned API value is presented at the command-line edge."""

  DATA = auto()
  VALUE = auto()
  SILENT = auto()


@dataclass(frozen=True)
class CommandSpec:
  """Pipeline metadata attached to one canonical API callable."""

  section: Section
  execution: Execution
  consumes_inputs: bool = False
  result: ResultPolicy = ResultPolicy.DATA
  order: int = 0

  def __post_init__(self) -> None:
    if not isinstance(self.section, Section) or not isinstance(
        self.execution, Execution) or not isinstance(self.result, ResultPolicy):
      raise TypeError(
          "CommandSpec section, execution, and result must be enums")
    if not isinstance(self.consumes_inputs, bool):
      raise TypeError("CommandSpec consumes_inputs must be a bool value")
    if not isinstance(self.order, int) or isinstance(self.order, bool):
      raise TypeError("CommandSpec order must be an integer")
    if self.execution is Execution.LOAD:
      if self.consumes_inputs:
        raise ValueError("LOAD commands cannot consume working-set inputs")
    if self.consumes_inputs and self.execution not in (Execution.MAP_APPEND,
                                                       Execution.COMBINE):
      raise ValueError(
          "only MAP_APPEND and COMBINE commands may consume their inputs")
    if self.execution in (Execution.TERMINAL_EACH, Execution.TERMINAL_ALL):
      if self.consumes_inputs:
        raise ValueError("terminal commands cannot consume working-set inputs")
      if self.result is ResultPolicy.DATA:
        raise ValueError("terminal commands need a non-DATA result policy")


@dataclass(frozen=True)
class DatasetRef:
  """Resolve this API dataset parameter from a unique working-set tag."""

  default_tag: str | None = None

  def __post_init__(self) -> None:
    if self.default_tag is not None and not self.default_tag:
      raise ValueError("DatasetRef default_tag must be non-empty when supplied")


@dataclass(frozen=True)
class PipelineInput:
  """Inject this parameter from the selected CLI working set."""


@dataclass(frozen=True)
class CliType:
  """Lossless CLI input type for a broader direct-Python annotation."""

  annotation: object


@dataclass(frozen=True)
class CliArgument:
  """Expose this API parameter as a positional command-line argument."""


@dataclass(frozen=True)
class ChoiceProvider:
  """Obtain an option's choices from the API registry returned by provider."""

  provider: Callable[[], object]

  def __post_init__(self) -> None:
    if not callable(self.provider):
      raise TypeError("ChoiceProvider requires a callable provider")


@dataclass(frozen=True)
class KeyValue:
  """Parse a mapping as repeated ``key=value`` option values."""


@dataclass(frozen=True)
class CliHidden:
  """Explicitly exclude a public callable from command generation."""

  reason: str

  def __post_init__(self) -> None:
    if not self.reason.strip():
      raise ValueError("CliHidden requires a non-empty reason")


_COMMAND_ATTR = "__postgkyl_command_spec__"
_HIDDEN_ATTR = "__postgkyl_cli_hidden__"


def command(spec: CommandSpec):
  """Attach ``spec`` to a callable without wrapping or registering it."""
  if not isinstance(spec, CommandSpec):
    raise TypeError("command() requires a CommandSpec")

  def decorate(fn):
    if hasattr(fn, _HIDDEN_ATTR):
      raise ValueError(f"{fn!r} is already marked CliHidden")
    previous = getattr(fn, _COMMAND_ATTR, None)
    if previous is not None and previous != spec:
      raise ValueError(f"{fn!r} already has a different CommandSpec")
    setattr(fn, _COMMAND_ATTR, spec)
    return fn

  return decorate


def hidden(reason: str):
  """Explicitly mark a public callable as unavailable from the CLI."""
  marker = CliHidden(reason)

  def decorate(fn):
    if hasattr(fn, _COMMAND_ATTR):
      raise ValueError(f"{fn!r} already has a CommandSpec")
    setattr(fn, _HIDDEN_ATTR, marker)
    return fn

  return decorate


def command_spec(fn) -> CommandSpec | None:
  """Return the immutable command metadata attached to ``fn``."""
  return getattr(fn, _COMMAND_ATTR, None)


def hidden_spec(fn) -> CliHidden | None:
  """Return the explicit CLI exclusion attached to ``fn``."""
  return getattr(fn, _HIDDEN_ATTR, None)


__all__ = [
    "ChoiceProvider",
    "CliArgument",
    "CliHidden",
    "CliType",
    "CommandSpec",
    "DatasetRef",
    "Execution",
    "KeyValue",
    "PipelineInput",
    "ResultPolicy",
    "Section",
    "command",
    "command_spec",
    "hidden",
    "hidden_spec",
]
"""Strict parser for the Google-style subset used by generated commands."""

from __future__ import annotations

from dataclasses import dataclass
import inspect
import re


class DocstringError(ValueError):
  """A canonical callable's documentation cannot be lowered losslessly."""


@dataclass(frozen=True)
class ParsedDocstring:
  summary: str
  long_help: str
  parameters: dict[str, str]


_SECTION = re.compile(r"^([A-Za-z][A-Za-z ]*):\s*$")
_ARG = re.compile(r"^\s{2,}(\*{0,2}[A-Za-z_]\w*)(?:\s*\([^)]*\))?:\s*(.*)$")


def _paragraph(lines: list[str]) -> str:
  out: list[str] = []
  for line in lines:
    if not line.strip() or _SECTION.match(line):
      if out:
        break
      continue
    out.append(line.strip())
  return " ".join(out)


def _narrative(lines: list[str]) -> str:
  """Return prose preceding the first structured docstring section."""
  end = next(
      (index for index, line in enumerate(lines) if _SECTION.match(line)),
      len(lines))
  return "\n".join(lines[:end]).strip()


def parse_docstring(obj,
                    *,
                    required: set[str] | None = None,
                    signature_names: set[str] | None = None) -> ParsedDocstring:
  """Parse and validate one canonical callable's command documentation."""
  qualname = f"{getattr(obj, '__module__', '<unknown>')}.{getattr(obj, '__qualname__', obj)}"
  doc = inspect.getdoc(obj)
  if not doc:
    raise DocstringError(f"{qualname}: missing docstring")
  lines = doc.splitlines()
  summary = _paragraph(lines)
  if not summary:
    raise DocstringError(f"{qualname}: missing first-paragraph description")

  entries: dict[str, str] = {}
  args_sections = [i for i, line in enumerate(lines) if line == "Args:"]
  if len(args_sections) > 1:
    raise DocstringError(f"{qualname}: duplicate Args sections")
  args_at = args_sections[0] if args_sections else None
  if args_at is not None:
    current: str | None = None
    chunks: list[str] = []

    def finish() -> None:
      if current is None:
        return
      text = " ".join(part for part in chunks if part).strip()
      if not text:
        raise DocstringError(
            f"{qualname}: parameter {current!r} has no description")
      if current in entries:
        raise DocstringError(
            f"{qualname}: parameter {current!r} is documented twice")
      entries[current] = text

    for line in lines[args_at + 1:]:
      if line and not line[0].isspace() and _SECTION.match(line):
        break
      match = _ARG.match(line)
      if match:
        finish()
        current = match.group(1).lstrip("*")
        chunks = [match.group(2).strip()]
      elif current is not None and (not line.strip()
                                    or line.startswith("    ")):
        chunks.append(line.strip())
      elif line.strip():
        raise DocstringError(
            f"{qualname}: malformed Args entry: {line.strip()!r}")
    finish()

  signature_names = signature_names or set()
  unknown = set(entries) - signature_names
  if unknown:
    names = ", ".join(sorted(unknown))
    raise DocstringError(
        f"{qualname}: documented parameter(s) absent from signature: {names}")
  for name in sorted(required or ()):
    if name not in entries:
      raise DocstringError(f"{qualname}: parameter {name!r} is undocumented")
  return ParsedDocstring(summary=summary,
                         long_help=_narrative(lines),
                         parameters=entries)


__all__ = ["DocstringError", "ParsedDocstring", "parse_docstring"]

